SET NOCOUNT ON;SET XACT_ABORT ON;IF (SELECT COUNT_BIG(*) FROM lab.OrderedFact)<>1200000 OR (SELECT COUNT_BIG(*) FROM lab.ShuffledFact)<>1200000 THROW 51006,'FAIL_RESULT_CONTRACT: IDX-010-Datenprofil fehlt.',1;SELECT object_name(object_id) TableName,state_desc,total_rows,deleted_rows,trim_reason_desc FROM sys.dm_db_column_store_row_group_physical_stats WHERE object_id IN(OBJECT_ID(N'lab.OrderedFact'),OBJECT_ID(N'lab.ShuffledFact'));PRINT 'SQLPERF_SUMMARY|PASS|OK';
